package app.space.notes;
import android.content.*;
import android.app.*;
import android.os.Build;
import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.File;
import java.util.*;
import app.space.notes.domain.*;
import app.space.notes.runtime.*;
import static org.junit.Assert.*;

/** Real Android RemoteViews, PendingIntents, alarm API, atomic snapshot and notification policy. */
@RunWith(AndroidJUnit4.class)
public class SystemSurfacesTest {
 private Context context;private File directory;private final List<String> notificationIds=new ArrayList<>();
 @Before public void setup(){Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();directory=new File(app.getCacheDir(),"system-"+UUID.randomUUID());assertTrue(directory.mkdirs());context=new ContextWrapper(app){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return directory;}@Override public SharedPreferences getSharedPreferences(String name,int mode){return app.getSharedPreferences(directory.getName()+"-"+name,mode);}};}
 @After public void cleanup() throws Exception {LocalReminders.reconcile(context,Collections.emptyList());NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);for(String id:notificationIds)manager.cancel(id,1);remove(directory);}
 private void remove(File f){File[] children=f.listFiles();if(children!=null)for(File c:children)remove(c);f.delete();}
 @Test public void schemaFiveRoundTripsReminderAndReadsSchemaFour() throws Exception {Note n=Note.create(1).reminder(4000,2);byte[] data=DocumentCodec.encode(Arrays.asList(n));assertEquals(4000,DocumentCodec.decode(data).get(0).reminderAt);org.json.JSONObject old=new org.json.JSONObject(new String(data,java.nio.charset.StandardCharsets.UTF_8)).put("version",4);old.getJSONArray("notes").getJSONObject(0).remove("reminderAt");assertEquals(0,DocumentCodec.decode(old.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)).get(0).reminderAt);}
 @Test public void changedReminderIsANonDestructiveImportConflict(){Note n=Note.create(1);Note changed=n.reminder(6000,1);NoteMerge.Plan plan=NoteMerge.preview(Arrays.asList(n),Arrays.asList(changed));assertEquals(1,plan.conflicts);assertEquals(2,plan.notes.size());assertEquals(6000,plan.notes.get(1).reminderAt);assertEquals(2,NoteMerge.preview(plan.notes,Arrays.asList(changed)).notes.size());}
 @Test public void privateSnapshotDoesNotContactSelectedProvider() throws Exception {Note n=Note.create(1);new NotesRepository(context).save(Arrays.asList(n));context.getSharedPreferences("mynotes-storage-v1",0).edit().putString("tree","content://unavailable/tree/test").commit();NotesRepository repository=new NotesRepository(context,uri->{throw new AssertionError("OS surfaces must not call external provider");});assertEquals(n.id,repository.localSnapshot().get(0).id);}
 @Test public void differentNotesHaveDistinctAndStablePendingIntents(){String a=UUID.randomUUID().toString(),b=UUID.randomUUID().toString();assertNotEquals(LocalReminders.alarm(context,a,1),LocalReminders.alarm(context,b,1));assertEquals(LocalReminders.alarm(context,a,1),LocalReminders.alarm(context,a,2));assertNotEquals(LocalReminders.open(context,a),LocalReminders.open(context,b));}
 @Test public void scheduleTrashAndClearUseInexactAlarmWithoutSpecialPermission() throws Exception {Note n=Note.create(System.currentTimeMillis()).reminder(System.currentTimeMillis()+86400000,System.currentTimeMillis());NotesRepository repository=new NotesRepository(context);repository.save(Arrays.asList(n));assertTrue(context.getSharedPreferences("mynotes-alarms-v1",0).getStringSet("ids",Collections.emptySet()).contains(n.id));repository.save(Arrays.asList(n.state(false,false,System.currentTimeMillis(),System.currentTimeMillis())));assertTrue(context.getSharedPreferences("mynotes-alarms-v1",0).getStringSet("ids",Collections.emptySet()).isEmpty());}
 @Test public void notificationRequiresDueMatchingUndeletedDocument(){Note n=Note.create(1).reminder(1000,2);assertFalse(LocalReminders.notifyDue(context,n,999,2000));assertFalse(LocalReminders.notifyDue(context,n,1000,999));assertFalse(LocalReminders.notifyDue(context,n.state(false,false,3,3),1000,2000));assertFalse(LocalReminders.notifyDue(context,n.reminder(0,3),1000,2000));}
 @Test public void dueNotificationHonorsOptionalPermissionAndIsNotDuplicated(){Note n=Note.create(1).edit("Local reminder fixture","private body",2).reminder(1000,3);notificationIds.add(n.id);boolean allowed=Build.VERSION.SDK_INT<33 || context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED;boolean posted=LocalReminders.notifyDue(context,n,1000,2000);assertEquals(allowed,posted);if(posted){assertFalse(LocalReminders.notifyDue(context,n,1000,2001));boolean found=false;long deadline=android.os.SystemClock.uptimeMillis()+3000;while(!found && android.os.SystemClock.uptimeMillis()<deadline){for(android.service.notification.StatusBarNotification active:((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications())if(n.id.equals(active.getTag())){found=true;assertEquals(Notification.VISIBILITY_PRIVATE,active.getNotification().visibility);}if(!found)android.os.SystemClock.sleep(25);}assertTrue(found);}}
 @Test public void widgetRemoteViewsInflateAndHideArchiveTrash() {List<Note> notes=Arrays.asList(Note.create(1).edit("Visible pinned","",2).state(true,false,0,3),Note.create(1).edit("Hidden archive","",2).state(true,true,0,3),Note.create(1).edit("Hidden trash","",2).state(false,false,3,3));InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{View view=NotesWidget.render(context,notes).apply(context,new FrameLayout(context));String text=((TextView)view.findViewById(app.space.notes.runtime.R.id.widget_row0)).getText().toString();assertTrue(text.contains("Visible pinned"));assertEquals(View.GONE,view.findViewById(app.space.notes.runtime.R.id.widget_row1).getVisibility());});}
 @Test public void emptyWidgetIsUsefulAndWidgetCanBeReplaced(){InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(int i=0;i<2;i++){View view=NotesWidget.render(context,Collections.emptyList()).apply(context,new FrameLayout(context));assertTrue(((TextView)view.findViewById(app.space.notes.runtime.R.id.widget_row0)).getText().toString().startsWith("No active notes"));}});}
 @Test public void widgetOpenIntentTargetsOnlyLocalHost(){Intent intent=LocalReminders.openIntent(context,"note id");assertEquals(context.getPackageName(),intent.getComponent().getPackageName());assertEquals("app.space.notes.NotesActivity",intent.getComponent().getClassName());assertEquals("note id",intent.getStringExtra("noteId"));assertEquals("mynotes",intent.getData().getScheme());}
}
